<?php
declare(strict_types=1);namespace Vendi\Inventory;use PDO;use RuntimeException;
final class ReceivingService{public function __construct(private PDO $db,private PresentationService $presentations,private LotService $lots,private SerialService $serials,private ?CostService $costs=null){}
 public function receive(int$b,int$branch,int$u,array$line,?int$purchaseId=null):array{$pid=(int)($line['product_id']??0);$pres=(int)($line['presentation_id']??0);$qty=(float)($line['quantity']??0);if(!$pid||!$pres||$qty<=0)throw new RuntimeException('Producto, presentación y cantidad son obligatorios.');$q=$this->db->prepare("SELECT tracks_lots,tracks_expiration,tracks_serials FROM products WHERE id=? AND business_id=?");$q->execute([$pid,$b]);$p=$q->fetch();if(!$p)throw new RuntimeException('Producto no encontrado.');$base=$this->presentations->toBase($b,$pres,$qty);$serials=$line['serials']??[];if((int)$p['tracks_serials']===1&&count($serials)!==(int)round($base))throw new RuntimeException('Debe capturar una serie por cada unidad base recibida.');if((int)$p['tracks_lots']===1&&trim((string)($line['lot_number']??''))==='')throw new RuntimeException('Este producto requiere lote.');if((int)$p['tracks_expiration']===1&&empty($line['expires_at']))throw new RuntimeException('Este producto requiere caducidad.');$own=!$this->db->inTransaction();if($own)$this->db->beginTransaction();try{$lotId=null;$costChange=null;if((int)$p['tracks_lots']===1)$lotId=$this->lots->receive($b,$branch,$pid,(string)$line['lot_number'],$base,$line['expires_at']??null,$line['manufactured_at']??null,$line['cost_per_base']??null);$this->db->prepare("INSERT INTO inventory(business_id,branch_id,product_id,qty) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE qty=qty+VALUES(qty)")->execute([$b,$branch,$pid,$base]);$this->db->prepare("INSERT INTO stock_movements(business_id,branch_id,product_id,user_id,type,qty,reference_type,reference_id) VALUES(?,?,?,?,'purchase',?,'purchase_receipt',?)")->execute([$b,$branch,$pid,$u,$base,$purchaseId]);foreach($serials as$s)$this->serials->receive($b,$branch,$pid,(string)$s,$lotId,$purchaseId);if(($line['update_cost']??false)&&isset($line['presentation_cost'])&&$this->costs)$costChange=$this->costs->updateFromReceiving($b,$branch,$u,$pid,$pres,(float)$line['presentation_cost'],$purchaseId);if($own)$this->db->commit();return['qty_base'=>$base,'lot_id'=>$lotId,'serials'=>count($serials),'cost_change'=>$costChange];}catch(\Throwable$e){if($own&&$this->db->inTransaction())$this->db->rollBack();throw$e;}}
}